-- What the Django version's data migrations give a new installation: the privacy notice
-- every installation replaces before opening forms, and the template "Externe Erstattung".
INSERT INTO "portal_privacynotice" ("version", "text", "created_at", "created_by") VALUES (1, '# Datenschutzhinweis noch nicht eingerichtet

Dieses Portal verarbeitet Kontaktdaten, Bankverbindungen, Angaben zu Auslagen, Belege und Unterschriften zur Erstellung und Übermittlung von Erstattungsanträgen.

Die verantwortliche Stelle muss diesen Hinweis vor der Veröffentlichung von Formularen ersetzen. Anzugeben sind die verantwortliche Organisation und ihre Kontaktdaten, Zwecke und Rechtsgrundlagen, Empfänger und Dienstleister, mögliche Drittlandübermittlungen, Speicherfristen und Betroffenenrechte.

# Löschfristen im Portal

Nicht eingereichte Entwürfe und Dateien werden nach 24 Stunden gelöscht. Die erstellte PDF löschen wir 7 Tage nach der Zustellung an die Buchhaltung. Alle übrigen Angaben, Belege und deine Unterschrift löschen wir 90 Tage nach dem Einreichen. Bei ungeklärter Zustellung bleibt der Antrag bis zur Klärung gespeichert. Anschließend bleiben für 30 weitere Tage nur Referenz, Zeitpunkt und Status erhalten. Außerhalb des Portals gelten die Fristen der jeweiligen Empfänger.

# Einrichtung erforderlich

Die Portalverwaltung veröffentlicht einen vollständigen Datenschutzhinweis als neue Version im Verwaltungsbereich.', now(), 'initial');--> statement-breakpoint
INSERT INTO "portal_formtemplate" ("name", "description", "intro", "declaration", "declaration_version", "travel", "mileage_enabled", "mileage_rate", "updated_at") VALUES ('Externe Erstattung', 'Auslagen externer Teilnehmender, z. B. für eine Werkstatt.', '', 'Hiermit bestätige ich, dass die angegebenen Auslagen tatsächlich entstanden sind, dem genannten Zweck dienen und bisher nicht erstattet wurden.', 'reimbursement-v1', 'optional', true, 0.30, now());--> statement-breakpoint
INSERT INTO "portal_templatefield" ("key", "label", "kind", "choices", "pattern", "required", "position", "template_id") SELECT field.key, field.label, 'text', '', '', field.required, field.position, template.id FROM "portal_formtemplate" template, (VALUES ('kst', 'Kostenstelle (KST)', true, 0), ('ktr', 'Kostenträger (KTR)', false, 1), ('id', 'ID', false, 2)) AS field(key, label, required, position) WHERE template.name = 'Externe Erstattung';
